"use strict";
eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   BB_SEQ_09: () => (/* binding */ BB_SEQ_09)\n/* harmony export */ });\n/* harmony import */ var _bb_seq_08__WEBPACK_IMPORTED_MODULE_0__ = __webpack_require__(/*! ./bb-seq-08 */ \"(ssr)/./src/lib/sequence-pages/bb-seq-08.ts\");\n\n// Blue Belt · Sequence #9 · Backside Pumping.\n// Mismo molde que la #8 (Marcelo 2026-09-09). Doctrina (doctrine_rules,\n// \"Backside pump: the M is the body\" y \"hand and elbow strike\"): la M es la\n// forma del CUERPO, no un trazo en la ola; la mano de ATRÁS (lado de la ola)\n// abre la palma hacia arriba y se tira hacia la línea; el codazo lidera la\n// bajada y cambia el riel; la línea en la cara es la misma que frontside.\nconst BB_SEQ_09 = {\n    id: \"BB-SEQ-09\",\n    belt: \"blue_belt\",\n    courseKey: \"blue_belt\",\n    number: 9,\n    title: \"Backside Pumping\",\n    // Como en la pestaña Course: FP1 → Posture (White) → BS mechanics → Pump.\n    stepIds: [\n        \"STP-035\",\n        \"STP-018\",\n        \"STP-038\",\n        \"STP-037\"\n    ],\n    think: {\n        whatIs: {\n            headline: \"Backside pumping is the same partnership — the wave’s energy plus your biomechanics — on a wave that breaks behind you: chest open to the wave, eyes over the back shoulder.\",\n            line: \"Arcs from the top of the face down through the middle and up again. One arc per pump.\",\n            where: \"Z2 to Z4 — the open face, wherever there is wall in front of you. It does not need to touch the lip.\",\n            whatFor: \"Speed you can spend on your backside: to make a section, to reach the pocket, to set up the bottom turn. The closer to the pocket, the more energy the wave gives you.\"\n        },\n        feet: _bb_seq_08__WEBPACK_IMPORTED_MODULE_0__.BB_SEQ_08.think.feet,\n        bodyFromLesson: \"STP-037\",\n        keyWords: [\n            {\n                label: \"Body\",\n                words: [\n                    \"Posture\",\n                    \"Palm up\",\n                    \"Extend\",\n                    \"Elbow (the M)\",\n                    \"Low\",\n                    \"Posture\"\n                ]\n            },\n            // Marcelo 2026-09-09: en backside la maniobra es el codazo, la M (no la Cruz).\n            {\n                label: \"Method\",\n                words: [\n                    \"Posture\",\n                    \"Rotation / rail\",\n                    \"Projection\",\n                    \"Maneuver (the elbow strike \\xb7 the M)\",\n                    \"Back to posture\"\n                ]\n            }\n        ],\n        board: _bb_seq_08__WEBPACK_IMPORTED_MODULE_0__.BB_SEQ_08.think.board\n    },\n    feel: {\n        visualize: \"Eyes closed, on the sand, chest open to an imaginary wave behind you. Run the six words in order and picture the line: up, down, up. Feel the back hand open palm up and throw toward the line, then the elbow strike that makes the M with your body. Ten pumps in your head.\",\n        land: [\n            \"DRL-BB-037\"\n        ],\n        skate: []\n    },\n    do: {\n        result: \"The board accelerates on every down-cycle on your backside: chest open, eyes over the back shoulder, the back hand throwing toward the line and the elbow strike changing the rail, with your weight never leaving the front foot.\",\n        missionId: \"MIS-BB-037\",\n        timing: \"Start the pump as soon as you have wall in front of you. The palm-up throw sets the line; the elbow strike lands the down-cycle on the lower third of the face; the up-cycle uses the top without touching the lip.\",\n        competence: \"Five backside waves with a clean pump line, eyes over the shoulder on where you want to go, body running the sequence on its own. If you can execute it and you feel comfortable, it is yours.\"\n    },\n    // El foco se elige de los pasos del cuerpo. Mismo orden que las key words.\n    details: [\n        {\n            key: \"posture\",\n            command: \"posture\",\n            title: \"Start with posture \\xb7 chest open, eyes over the shoulder\",\n            symptom: \"Closed chest facing the nose, eyes forward, standing tall or with the weight back.\",\n            indicators: [\n                {\n                    ok: \"The cycle starts in posture: low, weight on the front foot, chest open toward the wave, eyes over the back shoulder.\",\n                    no: \"Chest closed toward the nose or eyes looking forward; there is nothing to rotate from.\",\n                    fix: \"Open the chest, eyes over the shoulder, then move.\"\n                }\n            ],\n            deeper: {\n                label: \"BS Body Mechanics\",\n                lessonId: \"STP-038\",\n                drillId: \"DRL-BB-038\",\n                missionId: \"MIS-BB-038\"\n            }\n        },\n        {\n            key: \"palm\",\n            command: \"rail\",\n            title: \"1 \\xb7 Back hand, palm up, throws to the line \\xb7 get on the rail\",\n            symptom: \"The front hand leads or both hands swing; the line has no direction.\",\n            indicators: [\n                {\n                    ok: \"The back hand (wave side) opens the palm up and throws toward where you want to draw the line, before the legs extend.\",\n                    no: \"The front hand leads, or the palm stays down; the body does not get on the rail.\",\n                    fix: \"Palm up, throw to the line.\"\n                }\n            ],\n            deeper: {\n                label: \"Pump Backside\",\n                lessonId: \"STP-037\"\n            }\n        },\n        {\n            key: \"extend\",\n            command: \"projection\",\n            title: \"2 \\xb7 Extend, weight forward \\xb7 projection\",\n            symptom: \"The board stalls on the down-cycle; the weight went to the back foot.\",\n            indicators: [\n                {\n                    ok: \"At full extension the chest is still over the front foot, never behind it.\",\n                    no: \"The chest drops behind the front foot; the board loses speed.\",\n                    fix: \"Chest over the front foot.\"\n                },\n                {\n                    ok: \"The back foot only follows the rails; the front foot sinks the rail toward where you want to go.\",\n                    no: \"The weight drifts to the back foot; the board stalls.\",\n                    fix: \"Weight forward, front foot sinks the rail.\"\n                }\n            ],\n            deeper: {\n                label: \"Pump Backside\",\n                lessonId: \"STP-037\"\n            }\n        },\n        {\n            key: \"elbow\",\n            command: \"maneuver\",\n            title: \"3 \\xb7 Elbow strike \\xb7 the M is your body\",\n            symptom: \"The rail does not change; the arms wave an M in the air instead of striking.\",\n            indicators: [\n                {\n                    ok: \"One arm strikes with the elbow and the other arm is active and receives it: back and both elbows make the M with your body, and the rail changes.\",\n                    no: \"The arms draw an M in the air, or only one arm works; the rail does not change.\",\n                    fix: \"Strike the elbow, the other arm receives. The M is your body.\"\n                },\n                {\n                    ok: \"The elbow strike leads the way down: the board drops with energy.\",\n                    no: \"The head or the front hand tries to lead it down; nothing drops.\",\n                    fix: \"The elbow leads it down.\"\n                }\n            ],\n            deeper: {\n                label: \"Pump Backside\",\n                lessonId: \"STP-037\"\n            }\n        },\n        {\n            key: \"low\",\n            command: \"posture\",\n            title: \"4 \\xb7 Get low, back to posture\",\n            symptom: \"You end taller each cycle; the pump dies out.\",\n            indicators: [\n                {\n                    ok: \"You get low and land back in the same open-chest posture you started from, every cycle.\",\n                    no: \"You end taller or the chest closes; the pump dies out.\",\n                    fix: \"Low, then back to posture.\"\n                }\n            ],\n            deeper: {\n                label: \"Power Posture (White Belt)\",\n                lessonId: \"STP-018\",\n                drillId: \"DRL-WB-018-A\",\n                missionId: \"MIS-WB-018\"\n            }\n        }\n    ],\n    review: {\n        howItFeels: \"You feel you can generate speed forward on your backside using the face of the wave, with your chest open and your eyes already where you are going. You feel in control of your board and you are drawing your lines. The rhythm is yours: you decide when to take the wave’s energy and when to add your own.\"\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/lib/sequence-pages/bb-seq-09.ts\n");

